param(
    [string]$SourceRoot = 'D:\capture',
    [string]$OutputRoot = (Join-Path (Split-Path -Parent (Split-Path -Parent $PSScriptRoot)) 'matlab\session_2026_10_19\data')
)
$ErrorActionPreference='Stop'
New-Item -ItemType Directory -Force -Path $OutputRoot|Out-Null
$src=@'
using System;using System.Collections.Generic;using System.Globalization;using System.IO;using System.Linq;using System.Security.Cryptography;using System.Text;
public sealed class SpecInfo{public string Name,Kind,Dir,Hash;public byte[] Data;public bool Addr,Valid;public int Triggers,PeakCode,Carrier195Code;public double PeakBasebandMHz,PeakRfMHz,Carrier195MHz;}
public static class SpectrumMatExporter{
 const int N=65536;const double Fs=65.0,Center=200.0;
 static uint Hex(string s,int wanted){int f=0,st=0;for(int i=0;i<=s.Length;i++)if(i==s.Length||s[i]==','){if(f==wanted){uint v=0;for(int j=st;j<i;j++){char c=s[j];int d=c>='0'&&c<='9'?c-'0':c>='a'&&c<='f'?c-'a'+10:c>='A'&&c<='F'?c-'A'+10:-1;if(d<0)throw new InvalidDataException();v=(v<<4)|(uint)d;}return v;}f++;st=i+1;}throw new InvalidDataException();}
 static string Kind(string n){if(n.Contains("src_off"))return "generator_off";if(n.Contains("src_195"))return "generator_195MHz";if(n.Contains("src_205"))return "generator_205MHz";if(n.Contains("link_195"))return "link_195MHz";if(n.Contains("probe_checker"))return "probe_checker16";if(n.Contains("probe_black"))return "probe_black";if(n.Contains("probe_disconnected"))return "probe_disconnected";return "unknown";}
 static SpecInfo Load(string d){var q=new SpecInfo();q.Name=Path.GetFileName(d);q.Kind=Kind(q.Name);q.Dir=d;q.Data=new byte[N];q.Addr=true;q.Valid=true;int p=0;using(var r=new StreamReader(Path.Combine(d,"spectrum.csv"))){string h=r.ReadLine();r.ReadLine();if(h==null||!h.Contains("spec_eng_replay_data"))throw new InvalidDataException(q.Name+": bad header");string s;while((s=r.ReadLine())!=null){if(p>=N)throw new InvalidDataException(q.Name+": too many bins");byte v=(byte)Hex(s,3);int a=(int)Hex(s,4),valid=(int)Hex(s,5),tr=(int)Hex(s,6);if(a!=p)q.Addr=false;if(valid!=1)q.Valid=false;if(tr!=0)q.Triggers++;q.Data[p++]=v;}}if(p!=N)throw new InvalidDataException(q.Name+": incomplete spectrum");
  int best=-1;long bestScore=long.MinValue;for(int i=0;i<N;i++){double f=(i<N/2?i:i-N)*Fs/N;if(Math.Abs(f)<=0.1)continue;long score=0;for(int k=-16;k<=16;k++){int j=i+k;if(j>=0&&j<N)score+=q.Data[j];}if(score>bestScore){bestScore=score;best=i;}}
  int peak=best;byte pv=0;for(int k=-16;k<=16;k++){int j=best+k;if(j>=0&&j<N&&q.Data[j]>pv){pv=q.Data[j];peak=j;}}q.PeakCode=pv;q.PeakBasebandMHz=(peak<N/2?peak:peak-N)*Fs/N;q.PeakRfMHz=Center+q.PeakBasebandMHz;
  int cp=-1;byte cv=0;for(int i=0;i<N;i++){double f=(i<N/2?i:i-N)*Fs/N;if(Math.Abs(f+5.0)<=0.05&&q.Data[i]>cv){cv=q.Data[i];cp=i;}}q.Carrier195Code=cv;q.Carrier195MHz=Center+(cp<N/2?cp:cp-N)*Fs/N;
  using(var sha=SHA256.Create())q.Hash=BitConverter.ToString(sha.ComputeHash(q.Data)).Replace("-","");return q;}
 static int P(int n){return(n+7)&~7;}static void T(BinaryWriter w,int t,int b){w.Write(t);w.Write(b);}static void Z(BinaryWriter w,int n){for(int i=0;i<n;i++)w.Write((byte)0);}static byte[] A(string s){return Encoding.ASCII.GetBytes(s);}
 static void M(BinaryWriter w,string name,int cls,int typ,int[] dims,byte[] data){byte[] nb=A(name);int db=dims.Length*4,pay=16+8+P(db)+8+P(nb.Length)+8+P(data.Length);T(w,14,pay);T(w,6,8);w.Write((uint)cls);w.Write(0u);T(w,5,db);foreach(int d in dims)w.Write(d);Z(w,P(db)-db);T(w,1,nb.Length);w.Write(nb);Z(w,P(nb.Length)-nb.Length);T(w,typ,data.Length);w.Write(data);Z(w,P(data.Length)-data.Length);}
 static void D(BinaryWriter w,string n,int[] dims,double[] v){byte[] b=new byte[v.Length*8];Buffer.BlockCopy(v,0,b,0,b.Length);M(w,n,6,9,dims,b);}static void DS(BinaryWriter w,string n,double v){D(w,n,new[]{1,1},new[]{v});}
 static void C(BinaryWriter w,string n,string[] rows){int nr=rows.Length,nc=rows.Max(x=>x.Length);ushort[] u=new ushort[nr*nc];for(int c=0;c<nc;c++)for(int r=0;r<nr;r++)u[c*nr+r]=c<rows[r].Length?rows[r][c]:(ushort)' ';byte[] b=new byte[u.Length*2];Buffer.BlockCopy(u,0,b,0,b.Length);M(w,n,4,4,new[]{nr,nc},b);}
 static void Mat(string path,List<SpecInfo> q){using(var f=new FileStream(path,FileMode.Create))using(var w=new BinaryWriter(f)){byte[] h=A("MATLAB 5.0 MAT-file, VGA spectra 2026-10-19, generated "+DateTime.Now.ToString("s"));w.Write(h);Z(w,116-h.Length);Z(w,8);w.Write((ushort)0x0100);w.Write((byte)'I');w.Write((byte)'M');byte[] all=new byte[N*q.Count];for(int k=0;k<q.Count;k++)Buffer.BlockCopy(q[k].Data,0,all,k*N,N);M(w,"spectra",9,2,new[]{N,q.Count},all);C(w,"capture_names",q.Select(x=>x.Name).ToArray());C(w,"measurement_kinds",q.Select(x=>x.Kind).ToArray());C(w,"source_directories",q.Select(x=>x.Dir).ToArray());DS(w,"fft_length",N);DS(w,"sample_rate_hz",65000000);DS(w,"rf_center_hz",200000000);D(w,"baseband_frequency_hz",new[]{N,1},Enumerable.Range(0,N).Select(i=>(i<N/2?i:i-N)*65000000.0/N).ToArray());}}
 static string Q(string s){return"\""+s.Replace("\"","\"\"")+"\"";}
 static void Csv(string p,List<SpecInfo> q){using(var w=new StreamWriter(p,false,new UTF8Encoding(true))){w.WriteLine("capture_name,measurement_kind,bins,address_continuous,all_valid,trigger_count,global_peak_code,global_peak_baseband_mhz,global_peak_estimated_rf_mhz,carrier_195_code,carrier_195_frequency_mhz,data_sha256,source_directory");foreach(var x in q)w.WriteLine(string.Join(",",new[]{Q(x.Name),Q(x.Kind),N.ToString(),x.Addr.ToString(),x.Valid.ToString(),x.Triggers.ToString(),x.PeakCode.ToString(),x.PeakBasebandMHz.ToString("R",CultureInfo.InvariantCulture),x.PeakRfMHz.ToString("R",CultureInfo.InvariantCulture),x.Carrier195Code.ToString(),x.Carrier195MHz.ToString("R",CultureInfo.InvariantCulture),Q(x.Hash),Q(x.Dir)}));}}
 public static SpecInfo[] Run(string src,string mat,string csv){var ds=Directory.GetDirectories(src,"opt_*").Where(d=>File.Exists(Path.Combine(d,"spectrum.csv"))).OrderBy(d=>d,StringComparer.OrdinalIgnoreCase);var q=ds.Select(Load).ToList();if(q.Count==0)throw new Exception("No spectra");if(q.Any(x=>!x.Addr||!x.Valid))throw new Exception("Spectrum validation failed");Mat(mat,q);Csv(csv,q);return q.ToArray();}
}
'@
Add-Type -TypeDefinition $src -Language CSharp
$mat=Join-Path $OutputRoot 'all_spectra_2026_10_19.mat';$csv=Join-Path $OutputRoot 'spectrum_manifest.csv'
$q=[SpectrumMatExporter]::Run((Resolve-Path -LiteralPath $SourceRoot).Path,$mat,$csv)
Write-Host 'MATLAB_SPECTRUM_EXPORT_PASS';Write-Host "captures=$($q.Count)";Write-Host "mat=$mat";Write-Host "manifest=$csv"
